using System.Numerics;
using System.Runtime.CompilerServices;

namespace MinMax;

public static class RangeCalculator
{
    /// <summary>
    /// Returns the minimum and maximum values in <paramref name="values"/>.
    /// Uses SIMD vectorization with loop unrolling for high throughput on large spans.
    /// </summary>
    [MethodImpl(MethodImplOptions.AggressiveInlining)]
    public static (float Min, float Max) FindMinMax(ReadOnlySpan<float> values)
    {
        if (values.Length == 0)
            throw new ArgumentException("Span must not be empty.");

        if (Vector.IsHardwareAccelerated && values.Length >= Vector<float>.Count)
            return FindMinMaxVectorized(values);

        return FindMinMaxScalar(values);
    }

    private static (float Min, float Max) FindMinMaxScalar(ReadOnlySpan<float> values)
    {
        float min = values[0];
        float max = values[0];
        for (int i = 1; i < values.Length; i++)
        {
            if (values[i] < min) min = values[i];
            if (values[i] > max) max = values[i];
        }
        return (min, max);
    }

    private static (float Min, float Max) FindMinMaxVectorized(ReadOnlySpan<float> values)
    {
        int vcount = Vector<float>.Count;
        int i = 0;

        var vmin0 = new Vector<float>(values.Slice(i));
        var vmax0 = vmin0;
        i += vcount;

        var vmin1 = vmin0;
        var vmax1 = vmax0;

        // Process two vectors per iteration to hide instruction latency.
        int twoVec = vcount * 2;
        int lastTwoBlock = values.Length - twoVec;
        while (i <= lastTwoBlock)
        {
            var a = new Vector<float>(values.Slice(i));
            var b = new Vector<float>(values.Slice(i + vcount));
            vmin0 = Vector.Min(vmin0, a);
            vmax0 = Vector.Max(vmax0, a);
            vmin1 = Vector.Min(vmin1, b);
            vmax1 = Vector.Max(vmax1, b);
            i += twoVec;
        }

        // Merge the two accumulators.
        vmin0 = Vector.Min(vmin0, vmin1);
        vmax0 = Vector.Max(vmax0, vmax1);

        // Handle remaining full vector if any.
        if (i + vcount <= values.Length)
        {
            var v = new Vector<float>(values.Slice(i));
            vmin0 = Vector.Min(vmin0, v);
            vmax0 = Vector.Max(vmax0, v);
            i += vcount;
        }

        // Horizontal reduction.
        float min = vmin0[0];
        float max = vmax0[0];
        for (int j = 1; j < vcount; j++)
        {
            if (vmin0[j] < min) min = vmin0[j];
            if (vmax0[j] > max) max = vmax0[j];
        }

        // Scalar tail for remaining elements.
        for (; i < values.Length; i++)
        {
            if (values[i] < min) min = values[i];
            if (values[i] > max) max = values[i];
        }

        return (min, max);
    }
}

